{"kind": "content", "icon": "😴", "head": "योग निद्रा", "points": ["स्वामी सत्यानंद (मुंगेर) ने लोकप्रिय किया", "शवासन में लेटकर निर्देश सुनना", "शरीर के हर अंग पर ध्यान घुमाना", "संकल्प – एक अच्छा छोटा वाक्य", "गहरा विश्राम; तनाव, अनिद्रा में लाभ"], "say": "योग निद्रा एक गहरी विश्राम विधि है, जिसे मुंगेर के स्वामी सत्यानंद सरस्वती ने लोकप्रिय बनाया। इसमें शवासन में लेटकर किसी के निर्देश सुनते हैं। पहले एक छोटा संकल्प लिया जाता है, जैसे मैं मन लगाकर पढ़ूँगा। फिर ध्यान को शरीर के हर अंग पर एक एक करके घुमाया जाता है, दाएँ हाथ का अंगूठा, पहली उँगली, और ऐसे पूरे शरीर पर। इसमें शरीर सोता है पर मन जागा रहता है। बीस मिनट की योग निद्रा कई घंटे की नींद जितनी ताज़गी देती है।", "img": "yo_med.jpg", "cap": "शांति · फ़ोटो: PxHere (CC0)"},
{"kind": "content", "icon": "💧", "head": "षट्कर्म: शुद्धि क्रियाएँ", "points": ["हठयोग की छह शुद्धि क्रियाएँ", "नेति – नाक की सफ़ाई (जल नेति)", "धौति, नौली, बस्ति", "त्राटक – आँखें और एकाग्रता", "कपालभाति – फेफड़े; केवल प्रशिक्षक की देखरेख में"], "say": "हठयोग में शरीर की सफ़ाई के लिए छह क्रियाएँ बताई गई हैं, जिन्हें षट्कर्म कहते हैं। नेति, यानी नाक की सफ़ाई, जल नेति में टोंटी वाले लोटे से हल्का नमकीन गुनगुना पानी एक नथुने से डालकर दूसरे से निकाला जाता है। धौति, पेट की सफ़ाई। नौली, पेट की मांसपेशियों को घुमाना। बस्ति, आँतों की सफ़ाई। त्राटक, आँखों और एकाग्रता के लिए। और कपालभाति, फेफड़ों के लिए। इनमें से ज़्यादातर क्रियाएँ केवल प्रशिक्षित योग शिक्षक की देखरेख में ही करनी चाहिए।"},
{"kind": "content", "icon": "📖", "head": "परीक्षा से पहले 10 मिनट", "points": ["2 मिनट – पेट से गहरी साँस", "3 मिनट – अनुलोम-विलोम", "2 मिनट – भ्रामरी", "3 मिनट – ध्यान, सकारात्मक संकल्प", "परिणाम: डर कम, याददाश्त साफ़"], "say": "परीक्षा से पहले घबराहट होना स्वाभाविक है। उस दिन सुबह दस मिनट यह कीजिए। दो मिनट पेट से गहरी साँस। तीन मिनट अनुलोम विलोम। दो मिनट भ्रामरी। और तीन मिनट आँखें बंद करके ध्यान, साथ में एक सकारात्मक संकल्प, जैसे मैंने तैयारी की है, मैं शांत मन से लिखूँगा। इससे डर कम होगा, मन शांत होगा, और जो पढ़ा है वह साफ़ याद आएगा। परीक्षा हॉल में भी प्रश्नपत्र मिलने से पहले तीन गहरी साँस लीजिए।", "img": "y4_sunrise.jpg", "cap": "सुबह की शांति · फ़ोटो: Bhaskar India, Wikimedia Commons"},
{"kind": "table", "icon": "📚", "head": "प्राणायाम एक नज़र में", "eq": "प्राणायाम – कैसे – लाभ", "rows": [["प्राणायाम", "कैसे", "लाभ"], ["अनुलोम-विलोम", "बारी-बारी नथुने", "शांति, एकाग्रता"], ["कपालभाति", "ज़ोर से साँस बाहर", "पेट, पाचन"], ["भ्रामरी", "म्म्म गुंजन", "तनाव, नींद"], ["शीतली", "जीभ से साँस", "ठंडक"], ["उज्जायी", "गला सिकोड़कर", "थायरॉइड"]], "say": "प्राणायाम एक नज़र में। अनुलोम विलोम, बारी बारी नथुने से, शांति और एकाग्रता। कपालभाति, ज़ोर से साँस बाहर, पेट और पाचन। भ्रामरी, म्म्म गुंजन, तनाव कम और अच्छी नींद। शीतली, जीभ से साँस, ठंडक। उज्जायी, गला सिकोड़कर, थायरॉइड।"},
{"kind": "content", "icon": "⚠️", "head": "सावधानियाँ", "points": ["ख़ाली पेट, साफ़ हवा में", "ज़ोर-ज़बरदस्ती से साँस न रोकें", "चक्कर आए तो रुकें, सामान्य साँस", "बीमारी में डॉक्टर/प्रशिक्षक से पूछें", "बच्चों के लिए लंबा कुंभक नहीं"], "say": "प्राणायाम की कुछ सावधानियाँ। ख़ाली पेट और साफ़ हवा वाली जगह पर करें। साँस को ज़बरदस्ती बहुत देर तक न रोकें। अगर चक्कर आए या असहज लगे, तो तुरंत रुकें और सामान्य साँस लें। कोई बीमारी हो, जैसे दमा या हृदय रोग, तो डॉक्टर या प्रशिक्षक से पूछकर ही करें। आपकी उम्र में लंबा कुंभक, यानी साँस को देर तक रोकना, नहीं करना चाहिए, केवल सरल प्राणायाम ही करें।"},
{"kind": "content", "icon": "📋", "head": "सार", "points": ["प्राणायाम – साँस पर नियंत्रण; पूरक, रेचक, कुंभक", "पेट से गहरी साँस", "अनुलोम-विलोम, कपालभाति, भ्रामरी, शीतली, उज्जायी", "ध्यान, त्राटक, योग निद्रा", "षट्कर्म – प्रशिक्षक की देखरेख में"], "say": "सार। प्राणायाम साँस पर नियंत्रण है, जिसमें पूरक, रेचक और कुंभक होते हैं। हमेशा पेट से गहरी साँस लें। प्रमुख प्राणायाम हैं अनुलोम विलोम, कपालभाति, भ्रामरी, शीतली और उज्जायी। ध्यान, त्राटक और योग निद्रा मन को शांत करते हैं। और षट्कर्म शुद्धि क्रियाएँ हैं, जो प्रशिक्षक की देखरेख में ही करें।"},
{"kind": "content", "icon": "🌬️", "head": "साँस और जीवन का संबंध", "points": ["हम एक मिनट में 12–16 बार साँस लेते हैं", "साँस और मन जुड़े हैं", "गुस्से में साँस तेज़", "शांत मन में साँस धीमी"], "say": "हम रोज़ हज़ारों बार साँस लेते हैं और ज़्यादातर बिना ध्यान दिए। पर साँस और मन का गहरा रिश्ता है। जब हमें गुस्सा आता है, साँस तेज़ और छोटी हो जाती है। जब मन शांत होता है, साँस धीमी और गहरी हो जाती है। प्राणायाम इसी रिश्ते का उपयोग करता है। अगर हम साँस को धीमा और गहरा करना सीख लें, तो मन भी धीरे-धीरे शांत होने लगता है। इसीलिए योग में साँस को मन का लगाम कहा गया है।", "ext": 7},
{"kind": "question", "icon": "🤔", "head": "सोचिए", "q": "गुस्से में साँस कैसी हो जाती है?", "a": "तेज़ और छोटी", "pause": 4, "say": "अपना अनुभव याद कीजिए... जब कोई ग़ुस्सा करता है तो उसकी साँस तेज़ चलने लगती है और छोटी हो जाती है। इसके उलट, शांत बैठे व्यक्ति की साँस धीमी और गहरी होती है। इसलिए प्राणायाम से गहरी साँस लेकर हम मन शांत कर सकते हैं।", "ext": 7},
{"kind": "content", "icon": "🪷", "head": "प्राणायाम की तैयारी", "points": ["शांत और स्वच्छ जगह", "खाली पेट, सुबह का समय", "सीधी रीढ़, आरामदायक आसन", "ढीले कपड़े"], "say": "प्राणायाम करने से पहले कुछ तैयारी ज़रूरी है। जगह शांत और स्वच्छ हो, जहाँ ताज़ी हवा आए। सबसे अच्छा समय सुबह का है और पेट ख़ाली होना चाहिए, यानी खाने के कम से कम तीन-चार घंटे बाद। सुखासन या पद्मासन में रीढ़ सीधी रखकर बैठिए। कपड़े ढीले और आरामदायक पहनिए। आँखें बंद करके मन को दो-तीन गहरी साँसों के साथ शांत कर लीजिए, फिर अभ्यास शुरू कीजिए।", "ext": 7},
{"kind": "question", "icon": "🤔", "head": "सोचिए", "q": "प्राणायाम के लिए सबसे उपयुक्त समय और स्थिति क्या है?", "a": "सुबह का समय, खाली पेट, शांत स्वच्छ जगह", "pause": 4, "say": "याद कीजिए... सुबह की हवा ताज़ी होती है और मन शांत रहता है। पेट खाली हो तो साँस लेने में परेशानी नहीं होती। इसलिए सुबह, ख़ाली पेट और शांत जगह सबसे उत्तम मानी जाती है।", "ext": 7},
{"kind": "content", "icon": "🧘", "head": "अनुलोम-विलोम की विधि", "points": ["दाएँ हाथ से नासिका बंद करना", "बाईं से धीरे साँस लें", "दाईं से छोड़ें", "फिर उल्टा क्रम"], "say": "अनुलोम-विलोम को नाड़ी शोधन भी कहते हैं। सुखासन में बैठकर दाएँ हाथ के अँगूठे से दाईं नासिका बंद कीजिए और बाईं नासिका से धीरे-धीरे साँस भीतर लीजिए। फिर अनामिका से बाईं नासिका बंद करके दाईं से साँस छोड़िए। अब उसी दाईं से साँस लीजिए और बाईं से छोड़िए। यह एक चक्र हुआ। शुरू में पाँच से दस चक्र काफ़ी हैं। साँस लेना और छोड़ना बराबर या छोड़ना थोड़ा लंबा रखना अच्छा है।", "ext": 7},
{"kind": "question", "icon": "🤔", "head": "सोचिए", "q": "अनुलोम-विलोम से क्या लाभ होता है?", "a": "मन शांत होता है, एकाग्रता बढ़ती है, साँस की नलिकाएँ साफ़ रहती हैं", "pause": 4, "say": "सोचिए... यह प्राणायाम मन और शरीर दोनों के लिए अच्छा है। इससे तनाव घटता है, पढ़ाई में ध्यान लगता है और फेफड़े बेहतर काम करते हैं। इसलिए विद्यार्थियों के लिए यह बहुत उपयोगी है।", "ext": 7},
{"kind": "content", "icon": "🔥", "head": "कपालभाति और उसकी सावधानी", "points": ["झटके से साँस छोड़ना", "साँस लेना सहज", "पेट अंदर खिंचता है", "उच्च रक्तचाप में सावधानी"], "say": "कपालभाति में साँस झटके से बाहर छोड़ी जाती है और पेट अंदर की ओर खिंचता है। साँस लेना अपने आप सहज होता है। शुरू में एक मिनट करें, फिर धीरे-धीरे समय बढ़ाइए। इससे फेफड़े साफ़ होते हैं और शरीर में ऊर्जा आती है। पर ध्यान रखिए, उच्च रक्तचाप, हृदय रोग, हर्निया या गर्भावस्था में यह अभ्यास बिना डॉक्टर या गुरु की सलाह के न करें। चक्कर आए तो तुरंत रुक जाएँ।", "ext": 7},
{"kind": "question", "icon": "🤔", "head": "सोचिए", "q": "कपालभाति में किस पर ज़ोर होता है, साँस लेने पर या छोड़ने पर?", "a": "साँस छोड़ने पर", "pause": 4, "say": "याद कीजिए... इसमें हम पेट को झटके से अंदर खींचकर साँस बाहर निकालते हैं। साँस भीतर लेना अपने आप होता है। इसलिए ज़ोर साँस छोड़ने पर होता है।", "ext": 7},
{"kind": "content", "icon": "🐝", "head": "भ्रामरी और शीतली", "points": ["भ्रामरी: भौंरे की आवाज़", "तनाव और ग़ुस्से में उपयोगी", "शीतली: जीभ मोड़कर साँस", "गर्मी में शरीर ठंडा करे"], "say": "भ्रामरी में कानों को अँगुलियों से बंद करके साँस छोड़ते समय भौंरे जैसी गूँजती आवाज़ निकाली जाती है। इससे मन बहुत शांत होता है और तनाव या ग़ुस्सा घटता है। परीक्षा के डर में यह बहुत सहायक है। शीतली में जीभ को नली की तरह मोड़कर मुँह से साँस भीतर लेते हैं और नाक से छोड़ते हैं। इससे शरीर में ठंडक आती है, इसलिए गर्मियों में यह अच्छा है। सर्दी-ज़ुकाम में इसे न करें।", "ext": 7},
{"kind": "question", "icon": "🤔", "head": "सोचिए", "q": "शीतली प्राणायाम गर्मियों में क्यों उपयोगी है?", "a": "इससे शरीर को ठंडक मिलती है", "pause": 4, "say": "सोचिए... नाम में ही शीतल यानी ठंडा है। जीभ से ठंडी हवा भीतर जाती है और शरीर का ताप कम होता है। इसलिए गर्मियों में यह आरामदायक और लाभदायक है।", "ext": 7},
{"kind": "content", "icon": "🧠", "head": "ध्यान की सरल विधि", "points": ["सीधे बैठें", "आँखें बंद, साँस पर ध्यान", "विचार आएँ तो आने दें", "धीरे-धीरे दस मिनट"], "say": "ध्यान का मतलब है मन को एक जगह टिकाना। सीधे बैठकर आँखें बंद कीजिए और अपनी साँस के आने-जाने पर ध्यान दीजिए। मन भटके तो परेशान न हों, बस धीरे से फिर साँस पर लौट आइए। शुरू में पाँच मिनट और फिर दस मिनट तक बढ़ाइए। रोज़ का अभ्यास एकाग्रता, याददाश्त और भावनाओं के नियंत्रण में मदद करता है। विद्यार्थियों को पढ़ाई से पहले पाँच मिनट ध्यान ज़रूर करना चाहिए।", "ext": 7, "img": "yo_med.jpg", "cap": "कमल – ध्यान का प्रतीक · फ़ोटो: PxHere (CC0)"},
{"kind": "question", "icon": "🤔", "head": "सोचिए", "q": "ध्यान के दौरान मन भटक जाए तो क्या करना चाहिए?", "a": "बिना परेशान हुए धीरे से फिर साँस पर ध्यान लाना", "pause": 4, "say": "सोचिए... मन का भटकना स्वाभाविक है, इसमें कोई ग़लती नहीं। असली अभ्यास यह है कि भटकने का पता चलने पर धीरे से मन को वापस साँस पर ले आएँ। हर बार लौटना ही ध्यान की ट्रेनिंग है।", "ext": 7},
